// The published ESM/performance files have no accompanying declarations.
// Both builds expose the same API as the package's root declaration file.
declare module '@lastolivegames/becsy/lib/perf.js' {
  export * from '@lastolivegames/becsy';
}
declare module '@lastolivegames/becsy/lib/index.js' {
  export * from '@lastolivegames/becsy';
}
